namespace AmazonAppSync.Requests.Sourceapiassociations;

/// <summary>
/// The inputs of the GetSourceApiAssociation operation.
/// </summary>
public sealed record GetSourceApiAssociationRequest
{
    /// <summary>
    /// The identifier of the AppSync Merged API. This is generated by the AppSync service. In most cases, Merged APIs (especially in your account) only require the API ID value or ARN of the merged API. However, Merged APIs in other accounts (cross-account use cases) strictly require the full resource ARN of the merged API.
    /// </summary>
    public required string MergedApiIdentifier { get; init; }

    /// <summary>
    /// The ID generated by the AppSync service for the source API association.
    /// </summary>
    public required string AssociationId { get; init; }
}
